#!/usr/bin/env bash
set -e
# CODE Rx v2 - applies all changes as commits on top of your current branch
echo "Applying CODE Rx v2 (4 commits)..."
PATCH="$(mktemp)"
cat << 'PATCH_EOF' | base64 -d > "$PATCH"

PATCH_EOF
git am "$PATCH" 2>/dev/null || { echo "git am failed; trying git apply --3way..."; git apply --3way "$PATCH" && git add -A && git commit -m "feat: full backend, auth, PWA, forgot-password, members manager (no Supabase)" || { echo "Apply failed - paste the error here."; exit 1; }; }
rm -f "$PATCH"
echo ""
echo "Done! Now run:"
echo "   git log --oneline -6"
echo "   npm ci && npm run build"
echo "   npx wrangler pages dev dist --d1 DB=code-rx-db --r2 BUCKET=code-rx-storage"